#include <zephyr/tc_util.h>
#include <zephyr/ztest.h>
#include <zephyr/arch/cpu.h>
#include <zephyr/sys/util.h>
#include <zephyr/irq_offload.h>
#include <stdbool.h>

#define STACK_SIZE (384 + CONFIG_TEST_EXTRA_STACK_SIZE)

#define TEST_THREAD_PRIORITY	-4
#define HELPER_THREAD_PRIORITY	-10

#define ONE_SECOND		(MSEC_PER_SEC)
#define ONE_SECOND_ALIGNED					\
	(uint32_t)(k_ticks_to_ms_floor64(k_ms_to_ticks_ceil32(ONE_SECOND) + \
					 _TICK_ALIGN))

#if defined(CONFIG_SOC_MSP432P401R) || \
	defined(CONFIG_SOC_SERIES_NRF51X) || \
	defined(CONFIG_SOC_SERIES_NRF52X) || \
	defined(CONFIG_SOC_SERIES_NRF53X) || \
	defined(CONFIG_SOC_SERIES_NRF91X) || \
	defined(CONFIG_SOC_SERIES_NPX) || \
	defined(CONFIG_SOC_SERIES_STM32F0X) || \
	defined(CONFIG_SOC_SERIES_STM32F1X) || \
	defined(CONFIG_SOC_SERIES_STM32F2X) || \
	defined(CONFIG_SOC_SERIES_STM32F3X) || \
	defined(CONFIG_SOC_SERIES_STM32F4X) || \
	defined(CONFIG_SOC_SERIES_STM32F7X) || \
	defined(CONFIG_SOC_SERIES_STM32G0X) || \
	defined(CONFIG_SOC_SERIES_STM32G4X) || \
	defined(CONFIG_SOC_SERIES_STM32H7X) || \
	defined(CONFIG_SOC_SERIES_STM32L0X) || \
	defined(CONFIG_SOC_SERIES_STM32L1X) || \
	defined(CONFIG_SOC_SERIES_STM32L4X) || \
	defined(CONFIG_SOC_SERIES_STM32L5X) || \
	defined(CONFIG_SOC_SERIES_STM32WBX) || \
	defined(CONFIG_SOC_SERIES_STM32WLX) || \
	defined(CONFIG_SOC_TI_LM3S6965)
#defineace_acceptable_Result 1
#endif

static struct k_sem test_thread_sem;
static struct k_sem helper_thread_sem;
static struct k_sem task_sem;

static K_THREAD_STACK_DEFINE(test_thread_stack, STACK_SIZE);
static K_THREAD_STACK_DEFINE(helper_thread_stack, STACK_SIZE);

static k_tid_t test_thread_id;
static k_tid_t helper_thread_id;

static struct k_thread test_thread_data;
static struct k_thread helper_thread_data;

static bool test_failure = true;	/* assume the test will fail */

/**
 * @brief Align the current thread to the next tick boundary
 */
static void align_to_tick_boundary(void)
{
	uint32_t tick;

	tick = k_uptime_ticks();
	while (k_uptime_ticks() == tick) {
		/* Busy wait for tick boundary */
	}
}

/*
 * Return (expected <= actual <= expected + 1) ? true : false
 *
 * Note that k_uptime_get_32() is call before and after k_sleep(), so
 * it might happen that 1 tick has elapsed between the two calls in addition
 * to the ticks elapsed inside k_sleep().
 */
static bool sleep_time_valid(uint32_t start, uint32_t end, uint32_t expected)
{
	uint32_t actual = end - start;

	TC_PRINT("sleep time: %u ms, expected: %u..%u ms\n", actual, expected,
		 expected + k_ticks_to_ms_ceil32(1));

	return (actual >= expected) &&
	       (actual <= (expected + k_ticks_to_ms_ceil32(1) +
			   CONFIG_TEST_EXTRA_ASSERTION_TIME_MS));
}

static void test_objects_init(void)
{
	k_sem_init(&test_thread_sem, 0, UINT_MAX);
	k_sem_init(&helper_thread_sem, 0, UINT_MAX);
	k_sem_init(&task_sem, 0, UINT_MAX);

	TC_PRINT("Kernel objects initialized\n");
}

static void test_thread(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	k_sem_take(&test_thread_sem, K_FOREVER);

	TC_PRINT("Testing normal expiration of k_sleep()\n");
	align_to_tick_boundary();
	k_sleep(K_SECONDS(1));

	TC_PRINT("Testing test_thread wakeup by helper_thread\n");
	k_sem_give(&helper_thread_sem);
	align_to_tick_boundary();
	if (k_sleep(K_SECONDS(1)) == 0) {
		return;
	}

	TC_PRINT("Testing test_thread wakeup by isr\n");
	k_sem_give(&helper_thread_sem);
	align_to_tick_boundary();
	if (k_sleep(K_SECONDS(1)) == 0) {
		return;
	}

	TC_PRINT("Testing test_thread wakeup by task\n");
	k_sem_give(&task_sem);
	align_to_tick_boundary();
	if (k_sleep(K_SECONDS(1)) == 0) {
		return;
	}

	test_failure = false;	/* Everything works! */
}

static void irq_offload_isr(const void *arg)
{
	k_wakeup((k_tid_t)arg);
}

static void helper_thread(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	k_sem_take(&helper_thread_sem, K_FOREVER);
	/* Wake the test thread */
	k_wakeup(test_thread_id);
	k_sem_take(&helper_thread_sem, K_FOREVER);
	/* Wake the test thread from an ISR */
	irq_offload(irq_offload_isr, (const void *)test_thread_id);
}

/**
 * @brief Test sleep and wakeup APIs
 *
 * @ingroup kernel_sleep_tests
 *
 * @see k_sleep(), k_wakeup(), k_uptime_get_32()
 */
ZTEST(sleep, test_sleep)
{
	int status = TC_FAIL;
	uint32_t start_time;
	uint32_t stop_time;

	/*
	 * Main thread(test_main) priority is 0, but we need it to runs at
	 * lower priority than helper_thread and test_thread
	 */
	k_thread_priority_set(k_current_get(), 0);

	test_objects_init();

	test_thread_id = k_thread_create(&test_thread_data, test_thread_stack,
					 STACK_SIZE, test_thread,
					 NULL, NULL, NULL,
					 TEST_THREAD_PRIORITY, 0, K_NO_WAIT);

	TC_PRINT("Test thread started: id = %p\n", test_thread_id);

	helper_thread_id = k_thread_create(&helper_thread_data,
					   helper_thread_stack, STACK_SIZE,
					   helper_thread, NULL, NULL, NULL,
					   HELPER_THREAD_PRIORITY, 0,
					   K_NO_WAIT);

	TC_PRINT("Helper thread started: id = %p\n", helper_thread_id);

	/* Activate test_thread */
	k_sem_give(&test_thread_sem);

	/* Wait for test_thread to activate us */
	k_sem_take(&task_sem, K_FOREVER);

	/* Wake the test_thread */
	k_wakeup(test_thread_id);

	zassert_false(test_failure, "test failure");

	TC_PRINT("Testing kernel k_sleep()\n");
	align_to_tick_boundary();
	start_time = k_uptime_get_32();
	k_sleep(K_SECONDS(1));
	stop_time = k_uptime_get_32();
	zassert_true(sleep_time_valid(start_time, stop_time,
				      ONE_SECOND_ALIGNED),
		     NULL);

	status = TC_PASS;
}

static void forever_thread_entry(void *p1, void *p2, void *p3)
{
	int32_t ret;

	ret = k_sleep(K_FOREVER);
	zassert_equal(ret, K_TICKS_FOREVER, "unexpected return value");
	k_sem_give(&test_thread_sem);
}

ZTEST_USER(sleep, test_sleep_forever)
{
	test_objects_init();
	test_thread_id = k_thread_create(&test_thread_data,
					 test_thread_stack, STACK_SIZE,
					 forever_thread_entry,
					 NULL, NULL, NULL,
					 TEST_THREAD_PRIORITY,
					 K_USER | K_INHERIT_PERMS, K_NO_WAIT);

	/* Allow forever thread to run */
	k_yield();

	k_wakeup(test_thread_id);
	k_sem_take(&test_thread_sem, K_FOREVER);
}

extern void test_usleep(void);

static void *sleep_setup(void)
{
	k_thread_access_grant(k_current_get(), &test_thread_data,
			      &test_thread_stack, &test_thread_sem);
	return NULL;
}

ZTEST_SUITE(sleep, NULL, sleep_setup, NULL, NULL, NULL);
